package com.ecole.gestion_scolaire.hr.entity; import jakarta.persistence.*; import java.io.Serializable; import java.util.Objects;
@Entity @Table(name="teacher_subject") @IdClass(TeacherSubject.Key.class)
public class TeacherSubject { @Id @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="teacher_id") private Teacher teacher; @Id @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="subject_id") private Subject subject; public Teacher getTeacher(){return teacher;} public void setTeacher(Teacher v){teacher=v;} public Subject getSubject(){return subject;} public void setSubject(Subject v){subject=v;} public static class Key implements Serializable { public Long teacher; public Long subject; public Key(){} public boolean equals(Object o){return o instanceof Key k&&Objects.equals(teacher,k.teacher)&&Objects.equals(subject,k.subject);} public int hashCode(){return Objects.hash(teacher,subject);} }}